using System.Net.Mail;
using TheDomain.Application.Events;
using TheDomain.Domain.Branding;
using TheDomain.Domain.Media;
namespace TheDomain.Application.Branding;
public sealed class BrandingSettingsService(IBrandingSettingsRepository repository, TimeProvider timeProvider) : IBrandingSettingsService
{
    private const string DefaultName = "The Domain Entertainment";
    private const string DefaultDescription = "Premium entertainment experiences and events in Jordan.";
    private static readonly string[] Platforms = ["instagram", "facebook", "youtube", "tiktok", "linkedin", "x", "snapchat"];
    public async Task<BrandingSettingsResponse> GetAdminAsync(CancellationToken token) => await MapAdmin(await repository.GetAsync(false, token), token);
    public async Task<PublicBrandingSettingsResponse> GetPublicAsync(CancellationToken token) { var admin = await MapAdmin(await repository.GetAsync(false, token), token); return new(admin.SiteName, admin.BrandDescription, admin.DefaultSeoTitle, admin.DefaultSeoDescription, admin.PrimaryLogo, admin.AlternateLogo ?? admin.PrimaryLogo, admin.Favicon, admin.SocialImage, admin.PublicEmail, admin.PublicPhone, admin.WhatsApp, admin.PublicAddress, admin.SocialLinks); }
    public async Task<EventOperationResult<BrandingSettingsResponse>> UpdateAsync(UpdateBrandingSettingsRequest request, CancellationToken token)
    {
        var errors = Validate(request); if (errors.Count > 0) return EventOperationResult.Failure<BrandingSettingsResponse>(errors.ToArray());
        foreach (var id in new[] { request.PrimaryLogoMediaAssetId, request.AlternateLogoMediaAssetId, request.FaviconMediaAssetId, request.SocialImageMediaAssetId }.Where(id => id.HasValue).Select(id => id!.Value).Distinct()) { var media = await repository.FindMediaAsync(id, token); if (media is null) return EventOperationResult.NotFound<BrandingSettingsResponse>("A selected branding image was not found."); if (media.MediaType != MediaType.Image || media.IsArchived || media.ApprovalStatus != MediaApprovalStatus.Approved || !SafeHttps(media.Url)) return EventOperationResult.Conflict<BrandingSettingsResponse>("Active branding assets must be approved, non-archived HTTPS images."); }
        var links = NormalizeLinks(request.SocialLinks); var now = timeProvider.GetUtcNow(); var item = await repository.GetAsync(true, token);
        if (item is null) { item = new BrandingSettings(BrandingSettings.SingletonId, request.SiteName, request.DefaultSeoTitle, request.DefaultSeoDescription, now); repository.Add(item); }
        item.Apply(request.SiteName, request.BrandDescription, request.DefaultSeoTitle, request.DefaultSeoDescription, request.PrimaryLogoMediaAssetId, request.AlternateLogoMediaAssetId, request.FaviconMediaAssetId, request.SocialImageMediaAssetId, request.PublicEmail, request.PublicPhone, request.WhatsApp, request.PublicAddress, links.GetValueOrDefault("instagram"), links.GetValueOrDefault("facebook"), links.GetValueOrDefault("youtube"), links.GetValueOrDefault("tiktok"), links.GetValueOrDefault("linkedin"), links.GetValueOrDefault("x"), now, links.GetValueOrDefault("snapchat"));
        await repository.SaveChangesAsync(token); return EventOperationResult.Success(await MapAdmin(item, token));
    }
    private async Task<BrandingSettingsResponse> MapAdmin(BrandingSettings? item, CancellationToken token)
    {
        if (item is null) return new(DefaultName, DefaultDescription, DefaultName, DefaultDescription, null, null, null, null, null, null, null, null, null, null, null, null, new Dictionary<string, string>());
        async Task<BrandingMediaResponse?> Media(Guid? id) { if (id is null) return null; var value = await repository.FindMediaAsync(id.Value, token); return value is { MediaType: MediaType.Image, IsArchived: false, ApprovalStatus: MediaApprovalStatus.Approved } && SafeHttps(value.Url) ? new(value.Id, value.Url, value.AltText, value.Width, value.Height) : null; }
        return new(item.SiteName, item.BrandDescription, item.DefaultSeoTitle, item.DefaultSeoDescription, item.PrimaryLogoMediaAssetId, item.AlternateLogoMediaAssetId, item.FaviconMediaAssetId, item.SocialImageMediaAssetId, await Media(item.PrimaryLogoMediaAssetId), await Media(item.AlternateLogoMediaAssetId), await Media(item.FaviconMediaAssetId), await Media(item.SocialImageMediaAssetId), item.PublicEmail, item.PublicPhone, item.WhatsApp, item.PublicAddress, Links(item));
    }
    private static List<string> Validate(UpdateBrandingSettingsRequest request) { List<string> errors = []; if (string.IsNullOrWhiteSpace(request.SiteName) || request.SiteName.Trim().Length > 100) errors.Add("Site name is required and must not exceed 100 characters."); if (string.IsNullOrWhiteSpace(request.DefaultSeoTitle) || request.DefaultSeoTitle.Trim().Length > 120) errors.Add("Default SEO title is required and must not exceed 120 characters."); if (string.IsNullOrWhiteSpace(request.DefaultSeoDescription) || request.DefaultSeoDescription.Trim().Length > 320) errors.Add("Default SEO description is required and must not exceed 320 characters."); if (!string.IsNullOrWhiteSpace(request.PublicEmail)) try { _ = new MailAddress(request.PublicEmail.Trim()); } catch (FormatException) { errors.Add("Enter a valid public email address."); } if (!string.IsNullOrWhiteSpace(request.PublicPhone) && !ValidPhone(request.PublicPhone)) errors.Add("Enter a valid public phone number."); if (!string.IsNullOrWhiteSpace(request.WhatsApp) && !(ValidPhone(request.WhatsApp) || SafeHttps(request.WhatsApp))) errors.Add("Enter a valid WhatsApp number or HTTPS link."); foreach (var pair in request.SocialLinks ?? new Dictionary<string, string?>()) { if (!Platforms.Contains(pair.Key, StringComparer.OrdinalIgnoreCase)) errors.Add("An unsupported social platform was provided."); else if (!string.IsNullOrWhiteSpace(pair.Value) && !SafeHttps(pair.Value)) errors.Add($"{pair.Key} must use an HTTPS URL."); } return errors; }
    private static Dictionary<string, string> NormalizeLinks(IReadOnlyDictionary<string, string?>? links) => (links ?? new Dictionary<string, string?>()).Where(pair => Platforms.Contains(pair.Key, StringComparer.OrdinalIgnoreCase) && !string.IsNullOrWhiteSpace(pair.Value)).ToDictionary(pair => pair.Key.ToLowerInvariant(), pair => pair.Value!.Trim());
    private static Dictionary<string, string> Links(BrandingSettings item) => new[] { ("instagram", item.InstagramUrl), ("facebook", item.FacebookUrl), ("youtube", item.YouTubeUrl), ("tiktok", item.TikTokUrl), ("linkedin", item.LinkedInUrl), ("x", item.XUrl), ("snapchat", item.SnapchatUrl) }.Where(value => value.Item2 is not null).ToDictionary(value => value.Item1, value => value.Item2!);
    private static bool SafeHttps(string value) => Uri.TryCreate(value.Trim(), UriKind.Absolute, out var uri) && uri.Scheme == Uri.UriSchemeHttps;
    private static bool ValidPhone(string value) => value.Trim().All(character => char.IsDigit(character) || character is '+' or ' ' or '-' or '(' or ')') && value.Count(char.IsDigit) is >= 7 and <= 20;
}
